#include <Cellerator/compiler/diagnostics/implement_advisory_semantic_validators_v1.hh>
#include <cassert>
#include <array>
int main(){using namespace cellerator::compiler::diagnostics::v1; for(auto i:std::array{semantic_inconsistency::domain,semantic_inconsistency::order,semantic_inconsistency::generation,semantic_inconsistency::effect,semantic_inconsistency::numerical,semantic_inconsistency::identity})assert(validate_semantic_advisory({i,validation_mode::checked})==advisory_disposition::warning);assert(validate_semantic_advisory({semantic_inconsistency::domain,validation_mode::checked,false,true})==advisory_disposition::error);assert(validate_semantic_advisory({semantic_inconsistency::order,validation_mode::unsafe,false,false,true})==advisory_disposition::unsafe_continuation);assert(validate_semantic_advisory({semantic_inconsistency::identity,validation_mode::unsafe,true})==advisory_disposition::suppressed);assert(validate_semantic_advisory({semantic_inconsistency::domain,validation_mode::unsafe,false,false,true,false})==advisory_disposition::error);}
